INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('watislujv','Watislujv','demon','legitch',NULL,'','SCP Fragmented Veil','{"slug":"watislujv","name":"Watislujv","team":"demon","ability":"Each night*, choose a player: they die. You are sober, healthy & cannot die at night. [Character type & team rules can be broken]","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-031 is an amalgamous blob that enthralls those it can into a romantic trance, making them believe they are loved one of immeasurable value.","summaryBullets":["With the Watislujv in-play, how many of each character type is in-play, which players are on which team, and the evil team information can be changed to anything.","Added character types are also subject to being any alignment the Storyteller sees fit for the game, including Demons.","It is completely possible for there to be more or less number of evil players than usual for whatever reason, but the Storyteller will likely not add more than one.","Typically, all evil players will still learn each other & bluffs are unchanged, regardless if they are Minion/Demon, or not, but this is also subject to change for whatever reason.","Lastly, the Watislujv is sober & healthy at all times, and cannot be killed in the night."],"howToRun":["During setup, before giving the bag to the players, add or remove any Townsfolk, Outsiders, Minions, and Demons {{i|(except removing the Watislujv)}}.","When a player receives their character token during setup, correct their new alignment if intended to be different. After they see their character token, give them a thumbs-up or a thumbs-down {{i|(indicating their new alignment)}}.","During the first night, instead of doing the normal Minion Info and Demon Info steps, you may change it to however you see fit. Typically, you may want to run these steps as normal, but with evil players {{i|(except the Watislujv)}} as the Minions instead.","Each night except the first, wake the Watislujv. They point at any player. That player {{i|dies}} - mark them with the **DEAD** reminder. Put the Watislujv to sleep.","The Watislujv is always sober and health {{i|(even if they''re also marked}} **{{i|DRUNK}}** {{i|or}} **{{i|POISONED}}**,{{i|)}} and if they would die at night, they remain alive."],"tips":["When thinking of Minions to put onto the script or put into play with the Watislujv, consider if their ability would be balanced if the Alchemist character had it. However, also note that the Watislujv is sober and healthy at all times and cannot die at night, thus you are enabled to including more possible candidates for Minion abilities on the good team''s side, such as the Poisoner or Godfather.","**Optional rule:** Any good Demon(s) do not uphold the evil team''s win conditions when all evil evil Demons are dead."],"iconBy":"le_nuberto","jinxes":[{"name":"Boffin","align":"evil","text":"If the Boffin is good, they do not learn what ability they gave the Demon.","id":"boffin"},{"name":"Cult Leader","align":"good","text":"A starting evil Cult Leader cannot turn good.","id":"cultleader"},{"name":"Damsel","align":"good","text":"Only evil non-Demon players register as Minions to the Damsel.","id":"damsel"},{"name":"Mastermind","align":"evil","text":"If the Mastermind is good, they learn tonight if the Demon was executed today.","id":"mastermind"},{"name":"Scarlet Woman","align":"evil","text":"Minions register as the Demon to a good Scarlet Woman.","id":"scarletwoman"},{"name":"Spy","align":"evil","text":"A good Spy does not see the Grimoire.","id":"spy"},{"name":"Summoner","align":"evil","text":"If the Summoner is good, they don''t remove Demons in their setup-effect, and don''t make their chosen Demon evil.","id":"summoner"},{"name":"Vizier","align":"evil","text":"If the Vizier is good, they may only choose to execute immediately if three or more players voted, regardless of those players'' alignment.","id":"vizier"},{"name":"Widow","align":"evil","text":"A good Widow does not see the Grimoire, but still chooses a player to poison.","id":"widow"},{"name":"Umbilical","align":"evil","text":"If the Umbilical is good, instead of giving a 2nd Demon ability without the kill, the Watislujv is no longer sober, healthy, and immune from death at night.","slug":"umbilical"},{"name":"Esper","align":"evil","text":"There cannot be a good Esper.","id":"esper_the_bootleggers_anthology"},{"name":"Prankster","align":"good","text":"Only evil non-Demon players register as Minions to the Prankster.","id":"prankster_the_bootleggers_anthology"},{"name":"Blabbermouth","align":"good","text":"Only evil non-Demon players register as Minions to the Blabbermouth.","id":"blabbermouth_hblreleased"},{"name":"Chupacabra","align":"evil","text":"If the Chupacabra is good, the Chupacabra does not learn which players were nominated by evil & may choose any player. If that player was not nominated by evil today, they do not die.","id":"chupacabra_hblreleased"},{"name":"Leftenent","align":"evil","text":"If the Leftenent is good, they do not learn when a good player chose the Demon with their ability.","id":"leftenent_hblreleased"},{"name":"Ornithologist","align":"good","text":"If the Ornithologist is in play, evil players will draw blank tokens.","id":"ornithologist_2tfafullcharacterlist"},{"name":"Bloodless","align":"evil","text":"A good Bloodless does not see the Grimoire, but does learn when their ability has activated.","id":"bloodless_darkartists_stuff"}],"firstNight":0,"otherNight":35.031,"reminders":["Dead"],"setup":true,"otherNightReminder":"The Watislujv points to a player. That player dies","art":"art/watislujv.png","jsonId":"watislujv_scp_fragmented_veil","curata":false}','scp-fragmented-veil/watislujv','published',datetime('now'),datetime('now')),
('possessre','Possessre','demon','legitch',NULL,'','SCP Fragmented Veil','{"slug":"possessre","name":"Possessre","team":"demon","ability":"Each night*, choose a player: they die. You know 2-3 players & their characters. If they''re executed or killed by good, evil wins.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-035 is a lovecraftian eldritch comedy mask that lures victims into a false sense of security using social engineering (and also telepathy).","summaryBullets":["The Possessre starts with 2 or 3 good players in their sights.","On the first night, the Possessre wakes to learn these players and their characters.","If all the marked players are executed or killed by good abilities, evil wins.","This occurs even if any of the marked players survive their execution."],"howToRun":["While preparing the first night, put 2 to 3 of the Possessre''s **SINNER** reminder tokens by individual good character tokens.","During the first night, wake the Possessre and point to each player marked **SINNER** and show their character token to the Possessre.","Each night except the first, wake the Possessre. They point at any player. That player {{i|dies}} - mark them with the **DEAD** reminder. Put the the Possessre to sleep.","If a player marked with the **SINNER** reminder is executed or killed by a good ability, replace that reminder with the **BLASPHEMED** reminder. If there are to be no more players marked **SINNER**, declare that the game ends and evil wins."],"examples":["At the start of the game, the Pacifist and Sailor are marked to be the good players that cannot be misregistered. Over the course of the game, both of them are executed, and whilst they survive, evil wins."],"iconBy":"le_nuberto","jinxes":[{"name":"Vizier","align":"evil","text":"The Vizier cannot execute the last target of the Possessre.","id":"vizier"},{"name":"Steeplejack","align":"good","text":"If the Steeplejack dies at night & chooses the Possessre, they learn one of their unexecuted good player targets & their character. If they''re not in-play, this info is arbitrary.","id":"steeplejack_the_bootleggers_anthology"},{"name":"Porcher","align":"good","text":"If the Demon gains the Possessre''s ability, they learn the marked players without needing to wake.","id":"porcher_hblreleased"},{"name":"Heir","align":"evil","text":"Players that die in someone''s stead register as being executed to the Possessre.","id":"heir_darkartists_stuff"}],"firstNight":19.035,"otherNight":43.035,"reminders":["Sinner","Sinner","Sinner","Blasphemed","Blasphemed","Dead"],"setup":false,"firstNightReminder":"For each player marked ''Sinner'', point to them and show their character token.","otherNightReminder":"The Possessre points to a player. That player dies.","art":"art/possessre.png","jsonId":"possessre_scp_fragmented_veil","curata":false}','scp-fragmented-veil/possessre','published',datetime('now'),datetime('now')),
('pestalgue','Pestalgue','demon','legitch',NULL,'','SCP Fragmented Veil','{"slug":"pestalgue","name":"Pestalgue","team":"demon","ability":"Each night*, choose a player: they die. You know & have a good ability. If all Outsiders die, gain another. [+1 Outsider]","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-049 is a quixotic plague doctor that makes subordinate zombies through corpses of their victims.","summaryBullets":["The Pestalgue starts with a free Townsfolk or Outsider ability at their disposal.","This Townsfolk or Outsider ability can either be one that is already in-play, one that is from their bluffs, or one that is entirely not in-play.","The Pestalgue keeps this ability indefinitely. Should all Outsiders then be dead, they gain another.","The Pestalgue additionally knows exactly what Townsfolk/Outsider abilities they have."],"howToRun":["While setting up the game, before putting character tokens in the bag, add one extra Outsider character token and remove one Townsfolk character token.","During the first night, mark a Townsfolk or Outsider character token with the Pestalgue''s **USING ABILITY OF** reminder, or place a not in-play token by the Pestalgue''s character token. Wake the Pestalgue. Show the Pestalgue this Townsfolk/Outsider character token. Put the Pestalgue to sleep. Later on, if all Outsiders **are dead**, repeat this process. If the last living Outsider died during the day, wait until night to show them their new ability.","Each night except the first, wake the Pestalgue. They point at any player. That player dies.","Each time the Pestalgue wakes to use an ability at night, before doing so, show them the character token of what ability they are using."],"iconBy":"le_nuberto","customBoxes":[{"title":"Alternative JSON & How to Run (Older)","content":"If you want to use the older version of the Pestalgue, where it was a Dolomite/Vampire hybrid instead of the healthier design it is in now, use this JSON. This is quite overpowered, but could be found fun in groups that expect constant betrayal and chaos to be a type of bread and butter.\n\nWhile setting up the game, remove all but one Minion token, and add Outsider tokens for each Minion lost this way.\n\nEach night except the first, wake the Pestalgue. They point at any two players. Put the Pestalgue to sleep. One of the chosen players {{i|dies}} - mark them with the **DEAD** reminder. If there is no extra evil character in play and the Minion picked by the Pestalgue is not in play, perform the following on the other chosen player:\n\nShow the **YOU ARE** info token, then the Minion token. Show the **YOU ARE** info token, then give a thumbs down. Replace their character token with the Minion token and put the new Minion to sleep.\n\n**Pestalgue █~** (Demon)\nEach night*, choose 2 players: 1 dies, the other becomes a not-in-play evil Minion you choose, unless theres 1+ extra evil. [1 Minion, +1 Outsider for each lost]\n\n**Other nights:** The Pestalgue points to two players and a Minion on the character sheet - 1 of the players becomes that Minion and becomes evil if there already isn''t 1 extra evil player and that Minion is not in play, the other player dies.\n**Reminders:** Dead\n**Setup:** yes\n**Credit:** Ability: @legitch. Image: @le_nuberto\n\n**Jinxes:**\nBaron: If the Pestalgue chooses a player to become the evil Baron, up to two players become not-in-play Outsiders.\nEngineer: If the Engineer removes the Pestalgue before they have one more than their regular amount of Minions, they choose which players are which Minions until they have a regular amount, and the evil team learns each other.\nHatter: Only 1 jinxed character can be in play.\nPit-Hag: Only 1 jinxed character can be in play.\nSummoner: If the Pestalgue creates a Summoner, their ability cannot create a new evil Demon if there''s already 1 extra evil player. If the Summoner creates a not-in-play Demon, deaths tonight are arbitrary.\nClockwork Virus: If the Pestalgue chooses a player to become the evil Clockwork Virus, they instead become an out-of-play Outsider and infect that player with the Clockwork Virus if they already aren''t infected (this doesn''t infect the Pestalgue).\nUmbilical: The Demon cannot have the Pestalgue as their second ability.\nPorcher: If the Demon gains the Pestalgue''s ability, they may wake for it once to choose 1 player to become an evil Minion.\nPenitent: If the Pestalgue chooses to change their ability before they have one more than their regular amount of Minions, they choose which players are which Minions until they have a regular amount, and the evil team learns each other."}],"firstNight":7.049,"otherNight":45.049,"reminders":["Dead","Using ability of","Using ability of","?","?","?"],"setup":true,"firstNightReminder":"Wake the Pestalgue and show them the token of the good ability they have. Put the Pestalgue back to sleep.","otherNightReminder":"The Pestalgue points to a player. That player dies.","art":"art/pestalgue.png","jsonId":"pestalgue_scp_fragmented_veil","curata":false}','scp-fragmented-veil/pestalgue','published',datetime('now'),datetime('now')),
('harpodaarkniz','Harpodaarkniz','demon','legitch',NULL,'','SCP Fragmented Veil','{"slug":"harpodaarkniz","name":"Harpodaarkniz","team":"demon","ability":"Each night*, choose a player: they die. If executed by a good player, you don''t die unless they guess what Minions are in-play.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-058 is a hostile bovine heart with insect-like features that narrates complete nonsense.","summaryBullets":["The Harpodaarkniz cannot die if nominated & executed by a good player, unless they correctly guess what Minions are in-play."],"howToRun":["Each night except the first, wake the Harpodaarkniz. They point at any player. That player {{i|dies}} - mark them with the **DEAD** reminder. Put the Harpodaarkniz to sleep.","If the Harpodaarkniz was nominated & executed by a good player, they remain alive they correctly guess what Minions are in-play."],"tips":["It goes without saying, but the Harpodaarkniz is more fun on scripts without any loud Minions, or at the very least, Minions whose presence is only known to a select few people."],"iconBy":"_harryjamespotter","jinxes":[{"name":"Alsaahir","align":"good","text":"The Alsaahir must also guess what Minions are in-play in order to win the game.","id":"alsaahir"},{"name":"Hatter","align":"good","text":"If the Harpodaarkniz is in-play (after the Demon''s choice), Minions cannot choose to become not-in-play Minions, only swap around their characters.","id":"hatter"},{"name":"Pit-Hag","align":"evil","text":"The Pit-Hag cannot transform Minion players or players into new Minions whilst this is in-play.","id":"pithag"},{"name":"Slayer","align":"good","text":"The Slayer must also publicly guess what Minions are in-play in order to kill the Harpodaarkniz.","id":"slayer"},{"name":"Cleric","align":"good","text":"The Cleric must also publicly guess what Minions are in-play in order to kill the Harpodaarkniz.","id":"cleric_circus_music"},{"name":"Malum","align":"good","text":"If the Harpodaarkniz is in-play, the Malum is drunk.","id":"malum_circus_music"}],"firstNight":0,"otherNight":48.058,"reminders":["Dead"],"setup":false,"otherNightReminder":"The Harpodaarkniz points to a player. That player dies.","art":"art/harpodaarkniz.png","jsonId":"harpodaarkniz_scp_fragmented_veil","curata":false}','scp-fragmented-veil/harpodaarkniz','published',datetime('now'),datetime('now'));
